def translate(s):
    table={}
    bases='TCAG'
    aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
    for i in range(64):
        table[bases[i//16%4]+bases[i//4%4]+bases[i%4]]=aas[i]
    return ''.join(table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def all_orfs(s, strand):
    out=[]
    for frame in range(3):
        start=None
        for j in range(frame, len(s)-2, 3):
            c=s[j:j+3]
            if c=='ATG' and start is None:
                start=j
            if c in stops and start is not None:
                length=(j+3-start)//3
                out.append((start,j+3,length,translate(s[start:j+3])))
                start=None
        # trailing ORF without stop at end
        if start is not None:
            out.append((start,len(s), None, translate(s[start:])))
    return out

