def maximal_orfs(s):
    res=[]
    for frame in range(3):
        # positions of stops
        stop_positions=[j for j in range(frame, len(s)-2,3) if s[j:j+3] in stops]
        prev=-1
        segs=[]
        for j in stop_positions:
            segs.append((prev+3 if prev>=0 else frame, j))  # codon start..; 
            prev=j
        segs.append((prev+3, len(s)))
        for a,b in segs:
            if b-a>=150:
                res.append((a,b))
    return res
