kd = {'A':1.8,'R':-4.5,'N':-3.5,'D':-3.5,'C':2.5,'Q':-3.5,'E':-3.5,'G':-0.4,'H':-3.2,'I':4.5,'L':3.8,'K':-3.9,'M':1.9,'F':2.8,'P':-1.6,'S':-0.8,'T':-0.7,'W':-0.9,'Y':-1.3,'V':4.2,'X':0}
def tm(aa):
    w=19; thr=1.6
    scores=[]
    for i in range(len(aa)-w+1):
        scores.append(sum(kd.get(a,0) for a in aa[i:i+w])/w)
    # find peaks above threshold
    regions=[]
    i=0
    while i<len(scores):
        if scores[i]>thr:
            j=i
            while j<len(scores) and scores[j]>thr: j+=1
            regions.append((i+1,i+w, round(max(scores[i:j]),2)))
            i=j
        else: i+=1
    return regions

